parameters.functionCode:
const metrics = $input.all().map(i => i.json);
const anomalies = [];

for (const m of metrics) {
  if (!m.metric) continue;

  const current = parseInt(m.current_value) || 0;
  const avg = parseInt(m.avg_30d) || 1;
  const previous = parseInt(m.previous_value) || 0;

  // Z-score simplified: how many standard deviations from mean
  // Using 2x average as threshold for anomaly
  const ratio = current / Math.max(1, avg);
  const changeFromPrevious = previous > 0 ? ((current - previous) / previous * 100) : 0;

  let isAnomaly = false;
  let severity = 'info';
  let direction = 'normal';

  if (ratio >= 3) {
    isAnomaly = true;
    severity = 'critical';
    direction = 'spike';
  } else if (ratio >= 2) {
    isAnomaly = true;
    severity = 'warning';
    direction = 'high';
  } else if (ratio <= 0.2 && avg > 5) {
    isAnomaly = true;
    severity = 'warning';
    direction = 'drop';
  }

  if (isAnomaly) {
    anomalies.push({
      metric: m.metric,
      current_value: current,
      average_value: avg,
      ratio: Math.round(ratio * 100) / 100,
      change_percent: Math.round(changeFromPrevious),
      severity: severity,
      direction: direction,
      message: `${m.metric.replace(/_/g, ' ')}: ${current} (avg: ${avg}, ${ratio.toFixed(1)}x normal)`
    });
  }
}

return [{
  json: {
    has_anomalies: anomalies.length > 0,
    anomaly_count: anomalies.length,
    anomalies: anomalies,
    checked_at: new Date().toISOString()
  }
}];

